// spec: .qa/e2e/specs/add-candidate.md 3.5 (CHAIN step 2 of 2, one role per file)
// seed: tests/seed.company.spec.ts
// Needs step 1 (chain-daf026-visibility-1-hunter_plus.spec.ts) in the same run:
//   npx playwright test tests/add-candidate/chain-daf026-visibility --workers=1 --project=tests
// Opens the submissions only from the job list (company direct link to an anonymous submission is a known 404).
// Opening a submission sets «נצפה/תה» → @data.
import { test, expect, Page, Locator } from '@playwright/test';
import fs from 'fs';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/company.json') });
test.describe.configure({ mode: 'serial' });

const HANDOFF = path.join(__dirname, '../../.handoff/daf026-visibility.json');
type Cand = { last: string; phone: string; email: string; answer: string };
type Handoff = { runId: string; first: string; anon: Cand; full: Cand };
const handoff: Handoff | null = fs.existsSync(HANDOFF) ? JSON.parse(fs.readFileSync(HANDOFF, 'utf-8')) : null;

/** Phone digits '05XXXXXXXX' → matches «05X-XXX-XXXX», «05XXXXXXXX» and «+972 5X…». */
const phoneRe = (digits: string) => {
  const d = digits.replace(/\D/g, '').replace(/^0/, '');
  return new RegExp(`0?${d.split('').join('[\\s-]?')}`);
};

/** «המשרות שלי» → J-49 «QA company post test» → list of submitted candidates. */
async function openJ49Submissions(page: Page): Promise<Locator> {
  await page.goto('/my-jobs');
  await page.getByRole('main').getByText('QA company post test', { exact: true }).first().click();
  const list = page.getByRole('dialog').or(page.getByRole('main')).last();
  const tab = list.getByRole('tab', { name: /מועמדים שהוגשו|הצעות שהוגשו/ })
    .or(list.getByRole('button', { name: /מועמדים שהוגשו|הצעות שהוגשו/ }));
  if (await tab.count()) await tab.first().click();
  await expect(list.getByText('מועמד/ת אנונימי/ת').first()).toBeVisible({ timeout: 30_000 });
  return list;
}

test.describe('Candidate added by a headhunter is always anonymous — chain step 2 (#daf026)', () => {
  test.beforeEach(() => {
    test.skip(!handoff, 'run the chain from step 1 (chain-daf026-visibility-1-hunter_plus.spec.ts)');
  });

  test('CHAIN 2 — company: anonymous submission hides name, phone and e-mail @desktop @data #daf026', async ({ page }) => {
    test.setTimeout(180_000);
    const { anon } = handoff!;
    const list = await openJ49Submissions(page);

    // The list never shows the anonymous candidate's last name
    await expect(list.getByText(anon.last)).toHaveCount(0);

    // Open anonymous rows newest-first until the one with our screening answer
    const rows = list.getByText('מועמד/ת אנונימי/ת');
    const max = Math.min(await rows.count(), 6);
    let found: Locator | null = null;
    for (let i = 0; i < max && !found; i++) {
      await rows.nth(i).click();
      const dlg = page.getByRole('dialog', { name: /^הגשת מועמד/ }).last();
      await expect(dlg.getByText('הגשה אנונימית', { exact: true })).toBeVisible();
      if (await dlg.getByText(anon.answer).count()) { found = dlg; break; }
      await dlg.getByRole('button', { name: 'סגירה' }).first().click();
      await expect(dlg).toBeHidden();
    }
    expect(found, `anonymous submission with answer «${anon.answer}» among the first ${max} rows`).not.toBeNull();

    const text = (await found!.innerText()).replace(/‏|‎/g, '');
    expect(text, 'no last name').not.toContain(anon.last);
    expect(text, 'no e-mail').not.toContain(anon.email);
    expect(text, 'no phone').not.toMatch(phoneRe(anon.phone));
    await found!.getByRole('button', { name: 'סגירה' }).first().click();
  });

  test('CHAIN 2 — company: full-profile submission shows name, phone and e-mail @desktop @data #daf026', async ({ page }) => {
    test.setTimeout(120_000);
    const { first, full } = handoff!;
    const list = await openJ49Submissions(page);

    await list.getByText(`${first} ${full.last}`).first().click();
    const view = page.getByRole('dialog', { name: new RegExp(full.last) })
      .or(page.getByRole('main').filter({ has: page.getByRole('heading', { name: new RegExp(full.last) }) }))
      .last();
    await expect(view.getByRole('heading', { name: new RegExp(`${first}\\s+${full.last}`) })).toBeVisible({ timeout: 30_000 });
    await expect(view.getByText(full.email)).toBeVisible();
    const text = (await view.innerText()).replace(/‏|‎/g, '');
    expect(text, 'phone visible').toMatch(phoneRe(full.phone));
  });
});
